<?php
require dirname(__DIR__).'/_init.php';use App\Core\AccessControl;use App\Core\Database;use App\Core\CSRF;
AccessControl::require('consultations.manage');$db=Database::connection();$id=(int)($_GET['id']??$_POST['appointment_id']??0);$q=$db->prepare("SELECT a.*,p.id patient_id,p.full_name,p.patient_number,d.id doctor_id,d.name doctor_name FROM appointments a JOIN patients p ON p.id=a.patient_id JOIN doctors d ON d.id=a.doctor_id WHERE a.id=? AND a.status='checked_in'");$q->execute([$id]);$a=$q->fetch();if(!$a)exit('Checked-in appointment not found.');
$meds=$db->query("SELECT id,name FROM medicines WHERE is_active=1 ORDER BY name")->fetchAll();$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){CSRF::verify();try{$db->beginTransaction();$q=$db->prepare("INSERT INTO consultations(appointment_id,patient_id,doctor_id,diagnosis,notes) VALUES(?,?,?,?,?)");$q->execute([$id,$a['patient_id'],$a['doctor_id'],trim($_POST['diagnosis']),trim($_POST['notes']??'')]);$cid=(int)$db->lastInsertId();
foreach(($_POST['medicine_id']??[]) as $i=>$mid){if(!$mid)continue;$q=$db->prepare("INSERT INTO prescriptions(consultation_id,medicine_id,dosage,frequency,duration) VALUES(?,?,?,?,?)");$q->execute([$cid,(int)$mid,trim($_POST['dosage'][$i]??''),trim($_POST['frequency'][$i]??''),trim($_POST['duration'][$i]??'')]);}
$db->prepare("UPDATE appointments SET status='completed' WHERE id=?")->execute([$id]);$db->commit();header('Location: /consultations/index.php');exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log($e->getMessage());$err='Unable to save consultation. Please check the information.';}}
require dirname(__DIR__).'/_layout_top.php';?>
<h2>Consultation</h2><p><strong>Patient:</strong> <?=e($a['patient_number'].' - '.$a['full_name'])?> | <strong>Doctor:</strong> <?=e($a['doctor_name'])?></p><?php if($err):?><div class="alert alert-danger"><?=e($err)?></div><?php endif;?><form method="post" class="card p-4"><?=CSRF::field()?><input type="hidden" name="appointment_id" value="<?=$id?>"><label class="form-label">Diagnosis</label><textarea class="form-control mb-3" name="diagnosis" required></textarea><label class="form-label">Consultation notes</label><textarea class="form-control mb-3" name="notes"></textarea><h5>Prescription (optional)</h5><div class="row g-2"><?php for($i=0;$i<2;$i++):?><div class="col-md-3"><select class="form-select" name="medicine_id[]"><option value="">No medicine</option><?php foreach($meds as $m):?><option value="<?=$m['id']?>"><?=e($m['name'])?></option><?php endforeach;?></select></div><?php foreach(['dosage'=>'Dosage','frequency'=>'Frequency','duration'=>'Duration'] as $k=>$v):?><div class="col-md-3"><input class="form-control" name="<?=$k?>[]" placeholder="<?=e($v)?>"></div><?php endforeach;?><?php endfor;?></div><button class="btn btn-primary mt-4">Save consultation</button></form><?php require dirname(__DIR__).'/_layout_bottom.php';?>
